from experiments import *
import itertools,collections

def addseq(xs):
    s=0.
    for x in xs:s+=x
    return s

def tree(xs):
    while len(xs)>1:
        xs=[addseq(xs[j:j+2]) for j in range(0,len(xs),2)]
    return xs[0]

def reductions(errors,start):
    products=[e*e for e in errors]
    out={}
    for label,ps in [('all',products),('validation',products[start:])]:
        red={'forward':addseq(ps),'reverse':addseq(ps[::-1]),'tree':tree(ps),
          'fsum':math.fsum(ps),'sorted_up':addseq(sorted(ps)),
          'sorted_down':addseq(sorted(ps,reverse=True))}
        for lanes in [2,3,4,8]:
            sums=[addseq(ps[j::lanes]) for j in range(lanes)]
            red[f'lanes{lanes}']=addseq(sums)
            red[f'lanes{lanes}_tree']=tree(sums)
        # SIMD dot products can reduce adjacent pairs before accumulating.
        for block in [2,3,4,8]:
            red[f'blocks{block}']=addseq([addseq(ps[j:j+block]) for j in range(0,len(ps),block)])
        total=Q(0)
        for e in errors if label=='all' else errors[start:]:
            total=rnq(total+rnq(Q(e)*Q(e)))
        red['pc64']=float(total)
        for kind,score in red.items():
            out[label+'_'+kind+'_sse']=score
            for divisor in sorted(set([len(errors),len(errors)-1,len(errors)-2,len(errors)-start])):
                v=score/divisor
                out[label+'_'+kind+f'_mse{divisor}']=v
                out[label+'_'+kind+f'_rmse{divisor}']=math.sqrt(v)
    return out

def predictions(y):
    start=len(y)-window(len(y))
    candidates=[]
    for a,b in PARAMETERS:
        candidates.append((a,reductions(run(y,a,b,validation=start or None)['errors'],start)))
    return {key:min(candidates,key=lambda c:c[1][key])[0] for key in candidates[0][1]}

def audit():
    p=json.loads((OUT/'tie-followup-predictions.json').read_text())
    a=decoded('tie-followup'); candidates=None; fails=collections.Counter()
    for row in p['rows']:
        if row['id'].startswith('underflow'):continue
        pred=predictions(row['y'])
        matching={k for k,v in pred.items() if bits(v)==bits(a[row['id']])}
        if candidates is None:candidates=set(pred)
        candidates &=matching
        fails.update(k for k in pred if k not in matching)
    print('Survive',sorted(candidates))
    print('Fewest counterexamples',fails.most_common()[-20:])
    save('score-shape-retrospective.json',dict(
      protocol='Retrospective elimination only, not fresh evidence. 42 normal-scale tie-family cases; models that fail are refuted. Survivors must face new frozen probes.',
      survivors=sorted(candidates),fewest_counterexamples=sorted(fails.items(),key=lambda item:item[1])[:30],python_source=Path(__file__).read_text()))

if __name__=='__main__':audit()
